export type Cond = "day" | "dusk" | "storm" | "night";

/**
 * Hawaiʻi is a single timezone, so the hour is the same on the server and on the
 * phone — no effect, no hydration mismatch, no flash of the wrong sky.
 */
export function condNow(at = Date.now(), stormy = false): Cond {
  if (stormy) return "storm";
  const h = Number(new Intl.DateTimeFormat("en-US", { timeZone: "Pacific/Honolulu", hour: "numeric", hour12: false }).format(at));
  if (h >= 6 && h < 17) return "day";
  if (h >= 17 && h < 20) return "dusk";
  return "night";
}

/**
 * In dark mode the cards go volcanic, so a bright midday sky behind them would
 * fight the scheme. Dark mode therefore only ever shows the two dark scenes —
 * the time of day still moves, the range just narrows.
 */
const DARK_SWAP: Record<Cond, Cond> = { day: "dusk", dusk: "dusk", storm: "storm", night: "night" };


/** prefers-color-scheme as a subscription. Server snapshot is `false`, so the first
 *  paint matches the HTML and the scheme settles on hydration without a mismatch. */
export function useDarkScheme() {
  return useSyncExternalStore(
    (cb) => {
      const m = window.matchMedia("(prefers-color-scheme: dark)");
      m.addEventListener("change", cb);
      return () => m.removeEventListener("change", cb);
    },
    () => window.matchMedia("(prefers-color-scheme: dark)").matches,
    () => false,
  );
}

export default function IslandScene({ cond, dark = false, className = "" }: { cond: Cond; dark?: boolean; className?: string }) {
  const key = dark ? DARK_SWAP[cond] : cond;
  return (
    <div aria-hidden className={`pointer-events-none fixed inset-0 z-0 overflow-hidden ${className}`} style={{ height: "100lvh" }}>
      <svg
        viewBox="0 0 402 800"
        preserveAspectRatio="xMidYMid slice"
        className="block size-full"
        dangerouslySetInnerHTML={{ __html: SCENE[key] }}
      />
    </div>
  );
}
